import { renderHook } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import type { NormalizedLogEntry } from '@/types/kanban'
import { useChatMessages } from '@/hooks/use-chat-messages'

describe('useChatMessages — refresh-loss repro (BUG)', () => {
  // User report: "本来有的，刷新回来后就没了"
  // During live streaming the user sees: [thinking] [tool] [assistant text].
  // After refresh, only [tool] remains — both the thinking block AND the
  // assistant reply look gone. This test reproduces the "thinking disappears"
  // half on the Claude/stream-json path.
  //
  // Mechanism:
  //   use-chat-messages.ts:186-194 — when flushToolBuffer runs and there are
  //   non-todo tool items, it absorbs `pendingThinking` as the tool group's
  //   `description`. ToolItems.tsx:919 renders description as a single
  //   `<span className="truncate">` line in the header. Long thinking becomes
  //   a one-line ellipsis — visually "gone".
  //
  // During live streaming the user briefly sees thinking as a standalone
  // ThinkingChatMessage because entries arrive one by one: when only thinking
  // is in the log, the end-of-loop flushPendingThinking() (line 363) emits it
  // as standalone. Once tools arrive in a later rebuild, it gets absorbed.
  it('keeps thinking as standalone message when followed by tool group (currently absorbed as description)', () => {
    const logs: NormalizedLogEntry[] = [
      {
        entryType: 'thinking',
        content: '让我看看这个 SQL 查询的 JOIN 条件',
        timestamp: '2026-01-01T00:00:00Z',
        turnIndex: 0,
      },
      {
        entryType: 'tool-use',
        content: 'Read db/schema.ts',
        timestamp: '2026-01-01T00:00:01Z',
        turnIndex: 0,
        messageId: 't1',
        metadata: { toolCallId: 't1', isResult: false, toolName: 'Read' },
        toolDetail: { kind: 'file-read', toolName: 'Read', toolCallId: 't1', isResult: false },
      },
      {
        entryType: 'assistant-message',
        content: '问题出在 JOIN 条件上：left join 应该改成 inner join',
        timestamp: '2026-01-01T00:00:02Z',
        turnIndex: 0,
      },
    ]

    const { result } = renderHook(() => useChatMessages(logs))
    const { messages } = result.current

    // EXPECTED (matches what the user sees during live streaming):
    //   thinking + tool-group + assistant — 3 distinct messages.
    // ACTUAL (after refresh): tool-group(with description=thinking) + assistant
    //   — 2 messages, thinking absorbed into the group header.
    const types = messages.map(m => m.type)
    expect(types).toEqual(['thinking', 'tool-group', 'assistant'])
  })
})

