describe('useAcpTimeline — refresh-loss repro (BUG)', () => {
  // User report: "本来有的，刷新回来后就没了"
  // During streaming, entries trickle in and the user sees thinking + tool +
  // partial-assistant. Once the full assistant content has arrived (live tail
  // OR fresh /logs after refresh), the prefix-startsWith dedup at lines
  // 226-239 of use-acp-timeline.ts splices the thinking block away.
  //
  // The heuristic assumes "assistant starts with thinking content" means the
  // assistant is just a richer copy of the thinking — but in reality models
  // often only share the opening sentence, then diverge. We are dropping the
  // entire thinking block based on a single shared prefix.
  //
  // Contrast: the existing test "keeps standalone thinking when assistant
  // only partially overlaps" only covers the case where thinking is LONGER
  // than the matched prefix (so startsWith is false). The common case where
  // thinking is short and assistant starts with it is uncovered — that's
  // exactly what users notice as "刷新后思考没了".
  it('keeps short thinking when assistant happens to start with the same opening sentence', () => {
    const logs: NormalizedLogEntry[] = [
      {
        // Short thinking burst — engine emits one chunk before transitioning
        // to the actual reply. Common with OpenCode / Codex reasoning items.
        entryType: 'thinking',
        content: '让我看看这个 SQL 查询',
        timestamp: '2026-01-01T00:00:00Z',
        turnIndex: 0,
      },
      {
        entryType: 'tool-use',
        content: 'Read db/schema.ts',
        timestamp: '2026-01-01T00:00:01Z',
        turnIndex: 0,
        messageId: 't1',
        metadata: { toolCallId: 't1', isResult: false },
        toolDetail: { kind: 'file-read', toolName: 'Read', toolCallId: 't1', isResult: false },
      },
      {
        // Final assistant content happens to lead with the same opener.
        // After this entry arrives (live tail OR /logs refresh), dedup fires.
        entryType: 'assistant-message',
        content: '让我看看这个 SQL 查询的具体问题。JOIN 条件写反了，应该用 inner join',
        timestamp: '2026-01-01T00:00:02Z',
        turnIndex: 0,
      },
    ]

    const { items } = rebuildAcpTimeline(logs)

    // EXPECTED: thinking + tool-group + assistant — all 3 preserved.
    // ACTUAL: tool-group + assistant — thinking spliced away by the
    //         startsWith dedup at use-acp-timeline.ts:227.
    const types = items.map(i => i.type)
    expect(types).toEqual(['thinking', 'tool-group', 'entry'])
  })
})

